create extension if not exists pgcrypto;create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,created_at timestamptz default now());create table if not exists public.subjects(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,discipline text,description text,original_text text not null,created_at timestamptz default now(),updated_at timestamptz default now());create table if not exists public.topics(id uuid primary key default gen_random_uuid(),subject_id uuid references public.subjects(id) on delete cascade,name text not null,description text,order_index int default 0);create table if not exists public.questions(id uuid primary key default gen_random_uuid(),subject_id uuid references public.subjects(id) on delete cascade,topic_id uuid references public.topics(id) on delete set null,type text not null,question text not null,options jsonb default '[]',correct_answer text not null,explanation text,difficulty text default 'medium',created_at timestamptz default now());create table if not exists public.attempts(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,subject_id uuid references public.subjects(id) on delete cascade,game_type text,score int default 0,total int default 0,created_at timestamptz default now());create table if not exists public.answers(id uuid primary key default gen_random_uuid(),attempt_id uuid references public.attempts(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,question_id uuid references public.questions(id) on delete cascade,user_answer text,is_correct boolean default false,created_at timestamptz default now());alter table public.profiles enable row level security;alter table public.subjects enable row level security;alter table public.topics enable row level security;alter table public.questions enable row level security;alter table public.attempts enable row level security;alter table public.answers enable row level security;create policy "own subjects" on public.subjects for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own profiles" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);create policy "own topics" on public.topics for all using(exists(select 1 from public.subjects s where s.id=subject_id and s.user_id=auth.uid())) with check(exists(select 1 from public.subjects s where s.id=subject_id and s.user_id=auth.uid()));create policy "own questions" on public.questions for all using(exists(select 1 from public.subjects s where s.id=subject_id and s.user_id=auth.uid())) with check(exists(select 1 from public.subjects s where s.id=subject_id and s.user_id=auth.uid()));create policy "own attempts" on public.attempts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own answers" on public.answers for all using(auth.uid()=user_id) with check(auth.uid()=user_id);